package in.recallradar;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
enum IntakeStatus { REVIEW, READY, CONFIRMED }
@Entity @Table(name="intake_job") class IntakeJob { @Id UUID id; UUID organizationId; UUID submittedBy; String sourceType; String fileName; @Enumerated(EnumType.STRING) IntakeStatus status; Instant createdAt; protected IntakeJob(){} IntakeJob(UUID org,UUID user,String source,String name){id=UUID.randomUUID();organizationId=org;submittedBy=user;sourceType=source;fileName=name;status=IntakeStatus.REVIEW;createdAt=Instant.now();} }
@Entity @Table(name="intake_line") class IntakeLine { @Id UUID id; UUID jobId; int lineNumber; String ingredientName; String supplierName; String supplierBatchNumber; LocalDate expiryDate; BigDecimal quantity; String unit; String locationName; @Enumerated(EnumType.STRING) IntakeStatus status; String issue; UUID receiptLotId; Instant createdAt; protected IntakeLine(){} IntakeLine(UUID job,int line,String ingredient,String supplier,String batch,LocalDate expiry,BigDecimal quantity,String unit,String location,String issue){id=UUID.randomUUID();jobId=job;lineNumber=line;ingredientName=ingredient;supplierName=supplier;supplierBatchNumber=batch;expiryDate=expiry;this.quantity=quantity;this.unit=unit;locationName=location;this.issue=issue;status=issue==null?IntakeStatus.READY:IntakeStatus.REVIEW;createdAt=Instant.now();} void confirmed(UUID lot){receiptLotId=lot;status=IntakeStatus.CONFIRMED;} }
